import { Component, EventEmitter, Input, Output, ElementRef, ViewChild, AfterViewInit, SimpleChanges, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { VariablesService } from '../../../core/services/variables.service';
import { MatSelectModule } from '@angular/material/select';
import { FormsModule } from '@angular/forms';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { TranscriptService } from '../../../adminpanel/services/transcript/transcript.service';

@Component({
  selector: 'app-content-editable',
  standalone: true,
  imports: [CommonModule, MatSelectModule, FormsModule, NgScrollbarModule],
  template: `
    <div class="relative">
          <div class="font-semibold text-xs w-fit whitespace-nowrap text-grey border-none h-5 p-0 !shadow-none  rounded-none  bg-blue-100 px-1 py-1"
            #contentEditable
            [contentEditable]="!disabled"
            [attr.placeholder]="placeholder"
            [attr.maxlength]="maxlength"
            (input)="onInput($event)"
            (blur)="onBlur($event)"
            (keyup.enter)="onFocusOut.emit(value)"
            (focus)="onFocus()"></div>
    </div>
  `,
  styles: [`
    [contenteditable]:empty:before {
      content: attr(placeholder);
      color: #9CA3AF;
    }
    [contenteditable]:focus {
      outline: none;
    }
    [contenteditable] {
      white-space: pre-wrap;
      word-wrap: break-word;
      overflow-wrap: break-word;
    }
    .hidden-select {
      position: absolute;
      opacity: 0;
      pointer-events: none;
    }
    :host ::ng-deep .mat-mdc-select-panel {
      z-index: 1000;
    }
    :host ::ng-deep .ng-scrollbar {
      height: 100%;
    }
    :host ::ng-deep .ng-scrollbar-view {
      padding: 0;
    }
  `]
})
export class ContentEditableComponent implements AfterViewInit {
  @ViewChild('contentEditable') contentEditable: ElementRef;
  @ViewChild('matSelect') matSelect: any;
  @Input() disabled: boolean = false;
  @Input() formcontrolname: string;
  @Input() error: boolean = false;
  @Input() placeholder: string = '';
  @Input() value: any = '';
  @Input() minrows: number = 1;
  @Input() maxlength: number = 500;
  @Input() maxWidth: number = 0;
  @Input() minWidth: number = 200;
  @Input() suggestions: string[] = [];
  @Input() breakAtLength: number = 0;
  @Input() selectedTheme: any = { nCFontsize: 12 };
  @Output() valueChange = new EventEmitter<string>();
  @Output() onFocusOut = new EventEmitter<any>();

  selectedValue: string = '';
  filteredSuggestions: string[] = [];
  private debounceTimer: any;
  constructor(public vs: VariablesService, private transcriptS: TranscriptService,
    private cdr: ChangeDetectorRef
  ) { }

  ngAfterViewInit() {
    // Set content if there's a value
    if (this.value) {
      this.contentEditable.nativeElement.textContent = this.value;
    }
    
    // Focus the element
    this.contentEditable.nativeElement.focus();
    
    // Place cursor at the end of the text
    this.placeCursorAtEnd(this.contentEditable.nativeElement);
  }

  /**
   * Places the cursor at the end of the text in a contenteditable element
   */
  placeCursorAtEnd(element: HTMLElement) {
    // Create a new range
    const range = document.createRange();
    
    // Select all the content in the element
    range.selectNodeContents(element);
    
    // Collapse the range to the end (false means collapse to end)
    range.collapse(false);
    
    // Get the current selection
    const selection = window.getSelection();
    
    // Clear any existing selection
    selection?.removeAllRanges();
    
    // Add our new range with the cursor at the end
    selection?.addRange(range);
  }

  private getTextWithNewlines(element: HTMLElement): string {
    let text = '';
    const walk = document.createTreeWalker(element, NodeFilter.SHOW_TEXT, null);
    let node: Text | null;

    while (node = walk.nextNode() as Text) {
      text += node.textContent;
    }

    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = element.innerHTML;

    const brs = tempDiv.getElementsByTagName('br');
    for (let i = brs.length - 1; i >= 0; i--) {
      brs[i].replaceWith('\n');
    }

    const divs = tempDiv.getElementsByTagName('div');
    for (let i = divs.length - 1; i >= 0; i--) {
      divs[i].replaceWith('\n' + divs[i].textContent);
    }

    return tempDiv.textContent || '';
  }

  async onInput(event: Event) {
    const element = event.target as HTMLElement;
    let text = this.getTextWithNewlines(element).replace(/[\n\r]/g, '');

    if (text.length > this.maxlength) {
      text = text.slice(0, this.maxlength);
      element.textContent = text;
      
      // Place cursor at the end after truncation
      this.placeCursorAtEnd(element);
    }

    // Save emitted value
    this.valueChange.emit(text);

    // Clear previous debounce
    clearTimeout(this.debounceTimer);

    // Start new debounce
    this.debounceTimer = setTimeout(async () => {
      try {
        let res: any = await this.transcriptS.getFieldData(text, this.formcontrolname);
        this.suggestions = res.length > 0 ? res.map(e => e?.[this.formcontrolname] ?? '') : [];
        this.filteredSuggestions = this.suggestions;

        // Filter client-side if needed
        this.filteredSuggestions = this.suggestions.filter(suggestion =>
          suggestion.toLowerCase().includes(text.toLowerCase())
        );

        console.log('filteredSuggestions', this.matSelect.opened)
        if (this.filteredSuggestions.length === 0) {
          this.matSelect.close();
        } else {
          if (this.matSelect && !this.matSelect.opened) {
            console.log('Opening mat-select with suggestions:', this.filteredSuggestions);
            setTimeout(() => {
              this.matSelect.open();
              this.cdr.detectChanges(); // Ensure the view updates after opening the select
            }, 0); // Ensure the view updates before opening
          }
        }
      } catch (err) {
        console.error('Error fetching suggestions:', err);
      }
    }, 300); // 300ms delay after user stops typing
  }

  onBlur(event: FocusEvent) {
    const element = this.contentEditable.nativeElement;
    const text = this.getTextWithNewlines(element);
    element.textContent = text.trim();
    this.valueChange.emit(text.trim());
    this.onFocusOut.emit(text.trim());
  }

  async onFocus() {
    // console.log('Content editable focused, suggestions:', this.suggestions);

    let res: any = await this.transcriptS.getFieldData(this.contentEditable.nativeElement.textContent, this.formcontrolname)
    this.suggestions = res.length > 0 ? res.map(e => e[this.formcontrolname]) : [];
    this.filteredSuggestions = this.suggestions;
    if (this.suggestions.length > 0) {
      const currentText = this.contentEditable.nativeElement.textContent || '';
      this.filteredSuggestions = this.suggestions.filter(suggestion =>
        suggestion.toLowerCase().includes(currentText.toLowerCase())
      );
      // Only open if we have filtered suggestions
      if (this.filteredSuggestions.length > 0) {
        setTimeout(() => {
          this.matSelect.open();
        });
      }
    }
  }

  async selectSuggestion(suggestion: string) {
    console.log('Suggestion selected:', suggestion);
    const element = this.contentEditable.nativeElement;
    element.textContent = suggestion;
    this.valueChange.emit(suggestion);
    element.focus();
    
    // Place cursor at the end after selecting a suggestion
    this.placeCursorAtEnd(element);
  }
}