  async getTranscriptHtml(formData: any): Promise<SafeHtml> {
    const res = await firstValueFrom(
      this.http.get<{ base64: string }>(
        `${environment.cloudUrl2}${environment.realtimeserive}/transcript/html`,
        { params: formData }
      ).pipe(
        map(res => atob(res.base64))  // decode base64 to HTML string
      ));
    return this.sanitizer.bypassSecurityTrustHtml(res);
  }

  async getTranscriptHtmlFile(cPath: string, cTransid: string, type: string = 'FST'): Promise<{ msg: number, data?: SafeHtml, error?: any }> {
    try {
      const response: any = await firstValueFrom(
        this.http.get<{ base64: string }>(`${environment.cloudUrl2}${environment.realtimeserive}/transcript/html-file`, {
          params: { cPath, cTransid, type },
        })
      );

      if (!response?.base64) {
        return {
          msg: -1, error: response.error
        };
      }

      const html = atob(response.base64);  // decode base64
      return {
        msg: 1,
        data: this.sanitizer.bypassSecurityTrustHtml(html)
      };

    } catch (error) {
      debugger
      return {
        msg: -1,
        error
      };
    }
  }


  async printRawHtml(cPath: string, cTransid: string, type: string = 'FST') {
    // const htmlString: SafeHtml = await this.getTranscriptHtmlFile(cPath, cTransid, type);
    // const rawHtml = (htmlString as any).changingThisBreaksApplicationSecurity;
    // const printWindow = window.open('', '_blank', 'width=800,height=600');
    // if (!printWindow) return;

    // printWindow.document.addEventListener('visibilitychange', function () {
    //   if (document.visibilityState === 'hidden') {
    //     printWindow.document.close();
    //   }
    // });
    // printWindow.document.open();
    // printWindow.document.write(String(rawHtml.toString()));
    // printWindow.document.close();


    // printWindow.onload = () => {
    //   // printWindow.focus();
    //   // printWindow.print();
    //   // Optional: auto-close after printing
    //   // printWindow.close();
    // };


    // const htmlString: SafeHtml = await this.getTranscriptHtmlFile(cPath, cTransid, type);
    const filedata = await this.getTranscriptHtmlFile(cPath, cTransid, type)
    if (filedata.msg == -1) {
      this.tost.openSnackBar(`Error fetching HTML file: ${filedata.error}`, 'E');
      return;
    }
    const htmlString: SafeHtml = filedata.data;
    const rawHtml = (htmlString as any).changingThisBreaksApplicationSecurity;

    // Create a hidden iframe
    const printFrame = document.createElement('iframe');
    printFrame.style.position = 'absolute';
    printFrame.style.top = '-10000px';
    document.body.appendChild(printFrame);

    // Write the printable content to the iframe
    printFrame.contentDocument.open();
    printFrame.contentDocument.write(`
    <html>
      <head>
        <title>Print Preview</title>
        <style>
          @media print {
            body {
              margin: 1cm;
            }
          }
        </style>
      </head>
      <body>${rawHtml}</body>
    </html>
  `);
    printFrame.contentDocument.close();

    // Wait for the iframe to load the content, then print and remove the iframe
    printFrame.onload = function () {
      printFrame.contentWindow.print();
      setTimeout(() => {
        document.body.removeChild(printFrame);
      }, 1000);
    };
  }



  async publishTranscript(mdl: publishTranscriptRequest): Promise<any> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl2}${environment.realtimeserive}/transcript/publish`, mdl)
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return res;
      } if (res && res.msg == -1 && res?.isIgnoreErr == true) {
        return res;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return res;
      }
    } catch (err) {
      this.tost.openSnackBar(`Transcripr publish failed ${err}`, 'E');
      return { msg: -1, error: err, value: '' };
    }
  }

